function pluralize(word) {
  if (/(?:s|x|z|ch|sh)$/iu.test(word)) {
    return `${word}es`
  }

  if (/[bcdfghjklmnpqrstvwxyz]y$/iu.test(word)) {
    return `${word.slice(0, -1)}ies`
  }

  return `${word}s`
}

export function camel2under(value) {
  return value
    .replace(/(.)([\p{Lu}][\p{Ll}\p{M}]+)/gu, '$1_$2')
    .replace(/([\p{Ll}\p{M}\d])([\p{Lu}])/gu, '$1_$2')
    .toLowerCase()
}

export function under2camel(value) {
  let index = 0
  let output = ''
  let sawSegment = false

  while (index < value.length && value[index] === '_') {
    output += '_'
    index += 1
  }

  while (index < value.length) {
    const segmentStart = index

    while (index < value.length && value[index] !== '_') {
      index += 1
    }

    const segment = value.slice(segmentStart, index)
    output += capitalizeLikePython(segment)
    sawSegment = true

    if (index >= value.length) {
      break
    }

    const runStart = index

    while (index < value.length && value[index] === '_') {
      index += 1
    }

    const runLength = index - runStart

    if (index >= value.length) {
      output += '_'.repeat(runLength)
      break
    }

    output += '_'.repeat(runLength - 1)
  }

  if (!sawSegment) {
    return `${output}_`
  }

  return output
}

export function slugify(value, delim = '_') {
  const tokens = value.match(/[\p{L}\p{N}\p{M}\\]+/gu)

  if (!tokens) {
    return value.length === 0 ? '' : delim
  }

  return tokens.join(delim).toLowerCase()
}

