  const args = argv.slice(2)
  const extras = []
  let valueA
  let endOfOptions = false

  for (let index = 0; index < args.length; index += 1) {
    const token = args[index]

    if (endOfOptions) {
      extras.push(token)
      continue
    }

    if (token === '--') {
      endOfOptions = true
      continue
    }

    if (token === '-h' || (/^-h.+/.test(token) && !/^-\d/.test(token))) {
      return exitResult(0, 'stdout', helpText(programName))
    }

    if (token.startsWith('--')) {
      const { name, value } = splitLongOption(token)

