        const next = args[index + 1]

        if (next === undefined || isOptionLike(next)) {
          return exitResult(2, 'stderr', `${usageText(programName)}${programName}: error: argument --a: expected one argument\n`)
        }

        valueA = next
        index += 1
        continue
      }

      extras.push(token)
      continue
    }

    extras.push(token)
  }

  if (valueA === undefined) {
    return exitResult(2, 'stderr', `${usageText(programName)}${programName}: error: the following arguments are required: --a\n`)
