import { FrozenDict } from './dictutils.mjs'

function quoteForRepr(value) {
  if (value.includes("'") && !value.includes('"')) {
    return '"'
  }

  return "'"
}

function escapeForRepr(value, quote) {
  let output = ''

  for (const char of value) {
    if (char === '\\') {
      output += '\\\\'
    } else if (char === quote) {
      output += `\\${quote}`
    } else if (char === '\n') {
      output += '\\n'
    } else if (char === '\r') {
      output += '\\r'
    } else if (char === '\t') {
      output += '\\t'
    } else if (char === '\b') {
      output += '\\b'
    } else if (char === '\f') {
      output += '\\f'
    } else if (char === '\v') {
      output += '\\v'
    } else {
      const codePoint = char.codePointAt(0)

      if (codePoint !== undefined && ((codePoint >= 0x00 && codePoint < 0x20) || (codePoint >= 0x7f && codePoint < 0xa0))) {
        if (codePoint <= 0xff) {
          output += `\\x${codePoint.toString(16).padStart(2, '0')}`
        } else if (codePoint <= 0xffff) {
          output += `\\u${codePoint.toString(16).padStart(4, '0')}`
        } else {
          output += `\\U${codePoint.toString(16).padStart(8, '0')}`
        }
      } else {
        output += char
      }
    }
  }

  return output
}

function stringRepr(value) {
  const quote = quoteForRepr(value)
  return `${quote}${escapeForRepr(value, quote)}${quote}`
}

function mapEntries(value) {
  if (value instanceof FrozenDict) {
    return value.toEntriesArray()
  }

  if (value instanceof Map) {
    return Array.from(value.entries())
  }

  return Object.entries(value)
}

function dictRepr(value) {
  const body = mapEntries(value)
    .map(([key, entryValue]) => `${pythonRepr(key)}: ${pythonRepr(entryValue)}`)
    .join(', ')

  return `{${body}}`
}

export function pythonRepr(value) {
  if (typeof value === 'string') {
    return stringRepr(value)
  }

  if (typeof value === 'number' || typeof value === 'bigint') {
    return String(value)
  }

  if (Array.isArray(value)) {
    return `[${value.map((item) => pythonRepr(item)).join(', ')}]`
  }

  if (value instanceof FrozenDict) {
    return `FrozenDict(${dictRepr(value)})`
  }

  if (value instanceof Map || (value != null && value.constructor === Object)) {
    return dictRepr(value)
  }

  if (value === null) {
    return 'None'
  }

  if (value === true) {
    return 'True'
  }

  if (value === false) {
    return 'False'
  }

  return String(value)
}

export function printValue(value) {
  const rendered = typeof value === 'string' ? value : pythonRepr(value)
  process.stdout.write(`${rendered}\n`)
}

